"""blok_22_1_20.py — Hac sûresi makro profili + 22:1-20 okuma kaydı."""
import json, re

DIK = json.load(open('blok_dikey_22_1_20.json', encoding='utf-8'))
veri = json.load(open('kuran_veri.json', encoding='utf-8'))
AR = {}
for s in veri['sureler']:
    for a in s['ayetler']:
        AR[(s['no'], a['no'])] = a['ar']
# 22:1'in başındaki besmele okuma metninden ayrılır (defter n=9 zaten hariç tutuyor)
AR[(22, 1)] = re.sub(r'^بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\s*', '', AR[(22, 1)])

